import json
def cross(o,a,b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
def inH(p,h): 
    n=len(h)
    for k in range(n):
        if cross(h[k],h[(k+1)%n],p)<0: return False
    return True
def solve(g,color):
    H,W=len(g),len(g[0])
    pts=[(i,j) for i in range(H) for j in range(W) if g[i][j]==color]
    h=hull(pts)
    o=[r[:] for r in g]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=color and inH((i,j),h): o[i][j]=2
    return o
